import { renderBypassDiagram } from './ups-bypass.js';
const frac = (top, bottom) => `<span class="fraction"><span>${top}</span><span>${bottom}</span></span>`;
export function renderRecoveryTime() {
 return `<div class="recovery-derivation" aria-label="Recovery time equals energy to replace divided by source power minus load power. The capacitor is missing five kilojoules."><div class="derivation-row">t = ${frac('Energy to replace', 'Source power − Load power')} = ${frac('½C(V<sub>target</sub>² − V<sub>initial</sub>²)', 'P<sub>source</sub> − P<sub>load</sub>')}</div><div class="derivation-row"><span class="math-term">½C(V<sub>target</sub>² − V<sub>initial</sub>²)</span><span class="math-term">= 64 kJ − 59 kJ = <strong>5 kJ</strong></span></div><div class="derivation-row"><span class="math-term">P<sub>extra</sub> = P<sub>source</sub> − P<sub>load</sub></span></div><div class="derivation-result">Recovery time = ${frac('5 kJ', 'Extra power')}</div><p>Constant positive surplus at the DC bus</p></div>`;
}
const tx=(x,y,t,size=23,color='ink')=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${size}" fill="var(--${color})">${t}</text>`;
const ln=(d,color='green',width=4)=>`<path d="${d}" fill="none" stroke="var(--${color})" stroke-width="${width}" stroke-linecap="round"/>`;
const node=(x,y,w,h,title,detail)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="var(--panel)" stroke="var(--line)"/>${tx(x+w/2,y+34,title,22)}${detail?tx(x+w/2,y+65,detail,18):''}`;
export function renderStoredEnergyIsolation(compact=false) {
 const circuit=`${node(18,24,144,76,'AC supply','Disconnected')}${ln('M162 62H196 M236 62H284V91 M284 155V200','muted')}${ln('M196 62L226 37','muted')}${tx(215,19,'Open',17,'muted')}<rect x="239" y="91" width="90" height="64" rx="6" fill="var(--panel)" stroke="var(--line)"/>${tx(284,117,'Rectifier',17,'muted')}${tx(284,141,'AC → DC',15,'muted')}${node(18,190,144,76,'Battery','Still connected')}${ln('M162 228H284V200H350 M284 332H91V266')}${ln('M284 200V259 M284 285V332')}${ln('M263 261H305 M263 282H305','gold',6)}${tx(279,180,'DC bus',22,'gold')}${tx(253,378,'Capacitor retains charge',21,'gold')}`;
 const wave=Array.from({length:81},(_,i)=>`${i?'L':'M'}${32+i*4} ${110-40*Math.sin(i/80*4*Math.PI)}`).join(' ');
 const graphs=`${tx(190,30,'Current during normal operation',21)}${ln('M25 110H365','line',1)}${ln(wave,'green',3)}${tx(190,188,'AC crosses zero each half-cycle',20,'green')}${ln('M25 270H365','line',1)}${ln('M32 220H352','blue',3)}${tx(190,317,'DC has no periodic current zero',20,'blue')}${tx(190,369,'Current zero helps AC arc extinction',17)}${tx(190,396,'It does not establish safe isolation',17)}`;
 return `<div class="stored-energy-lesson"><div class="stored-energy-panels"><svg viewBox="0 0 380 420" role="img" aria-label="AC input is open, but the battery remains connected to the DC bus and the capacitor remains charged.">${circuit}</svg><svg viewBox="0 0 380 420" role="img" aria-label="Alternating current crosses zero; steady DC does not. A zero crossing is not proof that the circuit is de-energized.">${graphs}</svg></div><p class="isolation-principle">Isolate every source · manage stored energy · verify absence of voltage</p></div>`;
}
export function renderBypassCheck(state={},compact=false) {
 const answered=Boolean(state.bypassAnswer);
 const result=renderBypassDiagram({mode:'static',sourceAvailable:!answered,compact});
 return `<div class="bypass-exercise"><p class="service-scenario">The inverter has failed. Static bypass carries the load. Now utility power fails.</p><div class="ups-visual"><svg viewBox="${result.viewBox}" role="img" aria-label="A failed inverter blocks the battery path. The static bypass depends on its AC source.">${result.svg}</svg></div>${answered?`<div class="service-prompt">${state.bypassAnswer==='yes'?'No—the battery path still needs the failed inverter.':'Correct. The failed inverter blocks the battery path.'} A generator can restore bypass power after startup and transfer; it does not bridge this interruption.</div>`:'<p class="bypass-question">Will the load stay powered without interruption?</p>'}</div>`;
}
